data class ApiError(
    val error: Any?,
    val unknownFields: Map<String, Any?> = emptyMap(),
    val fieldsSet: Set<String> = setOf("error")
) : Json.Encodable {

    override fun toJson(): Any? {
        val result = linkedMapOf<String, Any?>()
        if (this.error != null || "error" in fieldsSet) result["error"] = this.error
        for ((key, item) in this.unknownFields) if (!result.containsKey(key)) result[key] = item
        return result
    }
    init {
        require(unknownFields.keys.none { it in setOf<String>("error") }) { "Declared field in unknownFields" }
        require(fieldsSet.all { it in setOf<String>("error") || it in unknownFields }) { "Unknown presence field" }
    }
    fun hasField(wireName: String): Boolean = (toJson() as Map<*, *>).containsKey(wireName)
    fun isNull(wireName: String): Boolean = hasField(wireName) && (toJson() as Map<*, *>)[wireName] == null
    fun withNull(wireName: String): ApiError = when (wireName) {
        "error" -> copy(error = null, fieldsSet = fieldsSet + wireName)
        else -> { require(wireName !in setOf<String>("error")) { "Field is not nullable" }; copy(unknownFields = unknownFields + (wireName to null), fieldsSet = fieldsSet + wireName) }
    }
    fun withoutField(wireName: String): ApiError = when (wireName) {
        "error" -> copy(error = null, fieldsSet = fieldsSet - wireName)
        else -> { require(wireName !in setOf<String>("error")) { "Field is not nullable" }; copy(unknownFields = unknownFields - wireName, fieldsSet = fieldsSet - wireName) }
    }

    companion object {
        fun fromJson(value: Any?): ApiError {
            val map = value as? Map<*, *> ?: emptyMap<Any?, Any?>()
            return ApiError(
            error = map["error"],
                unknownFields = map.filterKeys { it !is String || it !in setOf("error") }.mapKeys { it.key.toString() },
                fieldsSet = map.keys.map { it.toString() }.toSet()
            )
        }
    }
}

