public data class StreamOptions(
    val maxReconnects: Int = 0,
    val reconnectDelay: Long = 1000,
    val lastEventId: String? = null,
    val maxStreamEventBytes: Int = 1048576,
    val maxLineLength: Int = 1048576,
    val onReconnect: ((Int, String?) -> Unit)? = null,
)
public data class SseEvent<T>(val data: String, val id: String?, val event: String?, val retry: Long?, val value: T)
public class StreamingException(message: String, val lineNumber: Long? = null) : ApiException(message)

@OptIn(kotlinx.coroutines.InternalCoroutinesApi::class)
internal fun <T> streamingFlow(
    request: Request, prepare: (Request) -> java.net.http.HttpRequest.Builder,
    httpClient: () -> java.net.http.HttpClient,
    options: ClientOptions, stream: StreamOptions, kind: String, decoder: (Any?) -> Any?,
): kotlinx.coroutines.flow.Flow<T> = kotlinx.coroutines.flow.flow {
    require(stream.maxReconnects in 0..1000) { "maxReconnects must be from 0 through 1000" }
    require(stream.reconnectDelay in 0..60000) { "reconnectDelay must be from 0 through 60000 ms" }
    require(stream.maxStreamEventBytes in 1..67108864) { "maxStreamEventBytes must be from 1 byte through 64 MiB" }
    require(stream.maxLineLength in 1..67108864) { "maxLineLength must be from 1 byte through 64 MiB" }
    val sse = kind == "sse"
    var reconnects = 0
    var eventId = stream.lastEventId
    var serverRetry: Long? = null
    while (true) {
        var input: java.io.InputStream? = null
        try {
            val builder = prepare(request)
            // Resumption replays this exact request, so the id only ever returns to the origin that issued it.
            if (sse && eventId != null) builder.header("Last-Event-ID", eventId)
            val http = httpClient()
            val future = http.sendAsync(builder.build(), java.net.http.HttpResponse.BodyHandlers.ofInputStream())
