    private fun checkCall(call: Map<String, Any?>, seen: MutableSet<String>) {
        val id = str(call["id"]); val tool = str(call["tool"])
        if (id.isEmpty() || !seen.add(id) || tool !in allowed || !digest(str(call["arguments_hash"])) || call["mutation"] !is Boolean || flag(call, "mutation") != flag(obj(registry[tool]), "mutation")) throw refused("corrupt call state")
    }
    @Suppress("UNCHECKED_CAST") private fun mutable(value: Any?): MutableMap<String, Any?> = obj(value) as MutableMap<String, Any?>
    private fun used(): MutableMap<String, Any?> = mutable(state["used"])
    private fun begin() {
        if (!running.compareAndSet(false, true)) throw refused("session already running")
        if (storageFailure != null) { running.set(false); throw refused("checkpoint write failed; reload before continuing", storageFailure) }
    }
    private fun persist() {
        try { options.checkpoint.save(state) }
        catch (error: Exception) { storageFailure = error; throw error }
    }
    private fun charge(key: String, amount: Double) {
        val next = num(used()[key]) + amount
        if (!amount.isFinite() || amount < 0 || !next.isFinite() || next > limits.getValue(key)) throw refused("budget exceeded: " + key)
        used()[key] = next
    }
    private fun project(tool: String, value: Any?): Any? = clean(options.persistResult(tool, value)).also { charge("output_bytes", bytes(it).size.toDouble()) }
    private fun acknowledge(call: Map<String, Any?>, value: Any?) {
