        val receipt = call.toMutableMap(); receipt["result"] = project(str(call["tool"]), value)
        receipt["previous"] = if (before.isEmpty()) "0".repeat(64) else obj(before.last())["hash"]
        receipt["hash"] = null; receipt["hash"] = hash(bytes(receipt))
        state["receipts"] = before + receipt; state["pending"] = pending.filter { obj(it)["id"] != call["id"] }
        try { persist() } catch (error: Exception) { state["receipts"] = before; state["pending"] = pending; throw error }
    }
    /** Persist an externally verified outcome without invoking the SDK. */
