                charge("input_bytes", bytes(mapOf("protocol" to PROTOCOL, "input" to detachedInput, "results" to state["receipts"], "tools" to tools)).size.toDouble())
                val context = Context(PROTOCOL, clean(detachedInput), receipts, tools)
