                val proposal = kotlinx.coroutines.withTimeout(deadlineMillis()) { provider.propose(context, remaining) }
                if (proposal.completed && proposal.calls != null || !proposal.completed && proposal.result != null) throw refused("proposal must contain calls or final exclusively")
                charge("input_bytes", bytes(mapOf("usage" to mapOf("tokens" to proposal.usage.tokens, "cost" to proposal.usage.cost), "calls" to proposal.calls?.map { mapOf("id" to it.id, "tool" to it.tool, "arguments" to it.arguments) }, "completed" to proposal.completed, "result" to proposal.result)).size.toDouble())
                for ((key, amount) in mapOf("tokens" to proposal.usage.tokens, "cost" to proposal.usage.cost)) {
